pygments.formatters.__init__.get_formatt:
def get_formatter_for_filename(fn, **options):
    """
    Return a :class:`.Formatter` subclass instance that has a filename pattern
    matching `fn`. The formatter is given the `options` at its instantiation.

    Will raise :exc:`pygments.util.ClassNotFound` if no formatter for that filename
    is found.
    """
    fn = basename(fn)
    for (modname, name, _, filenames, _) in FORMATTERS.values():
        for filename in filenames:
            if _fn_matches(fn, filename):
                if name not in _formatter_cache:
                    _load_formatters(modname)
                return _formatter_cache[name](**options)
    for (_name, cls) in find_plugin_formatters():
        for filename in cls.filenames:
            if _fn_matches(fn, filename):
                return cls(**options)
    raise ClassNotFound(f'no formatter found for file name {fn!r}')

pygments.lexers._mysql_builtins.parse_it:
def parse_item_create_functions(f):
    """Parse MySQL function names from item_create.cc."""
    results = set()
    for m in re.finditer('{"(?P<function>[^"]+?)",\\s*SQL_F[^(]+?\\(', f, flags=re.I):
        results.add(m.group('function').lower())
    if not results:
        raise ValueError('No item_create functions found')
    return results

pygments.lexer.bygroups.callback:
def callback(lexer, match, ctx=None):
    for (i, action) in enumerate(args):
        if action is None:
            continue
        elif type(action) is _TokenType:
            data = match.group(i + 1)
            if data:
                yield (match.start(i + 1), action, data)
        else:
            data = match.group(i + 1)
            if data is not None:
                if ctx:
                    ctx.pos = match.start(i + 1)
                for item in action(lexer, _PseudoMatch(match.start(i + 1), data), ctx):
                    if item:
                        yield item
    if ctx:
        ctx.pos = match.end()

pygments.unistring._handle_runs:
def _handle_runs(char_list):
    buf = []
    for c in char_list:
        if len(c) == 1:
            if (buf and buf[-1][1] == chr(ord(c) - 1)):
                buf[-1] = (buf[-1][0], c)
            else:
                buf.append((c, c))
        else:
            buf.append((c, c))
    for (a, b) in buf:
        if a == b:
            yield a
        else:
            yield f'{a}-{b}'

pygments.filters.__init__.get_all_filter:
def get_all_filters():
    """Return a generator of all filter names."""
    yield from FILTERS
    for (name, _) in find_plugin_filters():
        yield name

pygments.lexers.robotframework.normalize:
def normalize(string, remove=''):
    string = string.lower()
    for char in remove + ' ':
        if char in string:
            string = string.replace(char, '')
    return string

pygments.formatters.html._get_ttype_clas:
def _get_ttype_class(ttype):
    fname = STANDARD_TYPES.get(ttype)
    if fname:
        return fname
    aname = ''
    while fname is None:
        aname = '-' + ttype[-1] + aname
        ttype = ttype.parent
        fname = STANDARD_TYPES.get(ttype)
    return fname + aname

pygments.lexers.__init__._load_lexers:
def _load_lexers(module_name):
    """Load a lexer (and all others in the module too)."""
    mod = __import__(module_name, None, None, ['__all__'])
    for lexer_name in mod.__all__:
        cls = getattr(mod, lexer_name)
        _lexer_cache[cls.name] = cls
